    if (window.logToMCP) {
      window.logToMCP(level, message, data);
    }
  }

  /**
   * Draw audio waveform visualization
   */
  drawWaveform(ctx, audioData) {
    const { width, height } = ctx.canvas;

    // Clear canvas
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, width, height);

    // Draw waveform
    if (audioData.length > 0) {
      ctx.strokeStyle = '#00ff00';
      ctx.lineWidth = 2;
      ctx.beginPath();

      const sliceWidth = width / audioData.length;
      let x = 0;

      for (let i = 0; i < audioData.length; i++) {
        const v = audioData[i] / 128.0;
        const y = v * height / 2;

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }

        x += sliceWidth;
      }

      ctx.stroke();
    } else {
      // Draw placeholder waveform
      ctx.strokeStyle = '#333333';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, height / 2);
      for (let x = 0; x < width; x += 10) {
        const y = height / 2 + Math.sin(x * 0.1) * 10;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
  }

  /**
   * Show error message
   */
  showError(message) {
    this.updateStatus('error', message);
    this.logToTerminal(`ERROR: ${message}`);
    console.error('Voice Control Error:', message);
  }

  /**
   * Cleanup resources
   */
  destroy() {
    this.deactivate();

    if (this.synthesis) {
      this.synthesis.cancel();
    }

    // Remove event listeners
    document.removeEventListener('keydown', this.handleKeyDown);

    console.log('🎤 Voice control system destroyed');
  }
}

